    it.todo(
      "sword (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G, remainingCap 600 G",
    );
    it.todo("second of the two 1500 G claims → payout 600 G, remainingCap 0 G (reduced to remaining cap)");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo(
      "policy covers two swords, damages contains two sword entries → each treated as a separate damage with its own deductible",
    );
    it.todo("more damage entries of a type than the policy covers → error (whole claim rejected)");
  });

  describe("errors", () => {
    it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
    it.todo("claim references a damage entry whose item is not part of the policy → error");
    it.todo("claim references a damage entry with an unknown item type → error");
    it.todo("claim contains a damage entry with amount -200 → error");
  });

  describe("CLI", () => {
    it.todo(
