import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it("empty item list → premium 5 G (only the processing fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });

      expect(result).toEqual({ results: [{ premium: 5 }] });
    });
    it("a sword → base premium 100 G, premium 115 G (100 + 10 first insurance + 5 fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("an amulet → base premium 60 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "amulet" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 71 }] });
    });
    it("a staff → base premium 80 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "staff" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 93 }] });
    });
    it("a potion → base premium 40 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "potion" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 49 }] });
    });
    it("a single rune → base premium 25 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "rune" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 33 }] });
    });
    it("a single moonstone → base premium 25 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 33 }] });
    });
  });

  describe("quote — building block of 3 alike components", () => {
    it("2 runes → 50 G base premium", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 60 }] });
    });
    it("3 runes → 60 G base premium (block applies)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 71 }] });
    });
    it("4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("7 runes → 175 G base premium", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 198 }] });
    });
    it("2 runes + 1 moonstone → 75 G base premium (no block: different types)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 88 }] });
    });
    it("3 runes + 3 moonstones → 120 G base premium (two separate blocks)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              ...Array.from({ length: 3 }, () => ({ type: "rune" })),
              ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 137 }] });
    });
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("cursed sword adds a 50 % risk surcharge on the item's base premium");
    it.todo("sword with enchantment 5 → high-enchantment surcharge of 30 % applies");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("sword with enchantment 5 and cursed → both surcharges apply");
    it.todo(
      "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (only on the sword) → 210 G before further modifiers and fee",
    );
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("first insurance carries a 10 % initial assessment surcharge on the policy base premium");
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("second contract of a scenario → 15 % follow-up discount on the policy base premium");
    it.todo("first insurance surcharge still applies on a follow-up contract");
    it.todo("a 5 G processing fee is added at the very end of every premium");
  });

  describe("quote — rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed sword (steel, ench. 3) → premium 165 G");
    it.todo(
      "long-standing customer (3 years), second quote, cursed sword (steel, ench. 7) → premium 160 G",
    );
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G (deductible 100 G)");
    it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");
  });

  describe("claim — special clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("claim — deductible per damage event", () => {
    it.todo(
      "dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (100 G deductible per damaged item)",
    );
  });

  describe("claim — rounding in the MHPCO's favor", () => {
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("a cursed sword → cap 2000 G (based on unmodified insurance value)");
    it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
    it.todo(
      "sword (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G, remainingCap 600 G",
    );
    it.todo("second of the two 1500 G claims → payout 600 G, remainingCap 0 G (reduced to remaining cap)");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo(
      "policy covers two swords, damages contains two sword entries → each treated as a separate damage with its own deductible",
    );
    it.todo("more damage entries of a type than the policy covers → error (whole claim rejected)");
  });

  describe("errors", () => {
    it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
    it.todo("claim references a damage entry whose item is not part of the policy → error");
    it.todo("claim references a damage entry with an unknown item type → error");
    it.todo("claim contains a damage entry with amount -200 → error");
  });

  describe("CLI", () => {
    it.todo(
      "reads a scenario from stdin and writes {results: [...]} to stdout, same length and order as steps",
    );
    it.todo("exits with a non-zero status code and writes an error description to stderr on invalid input");
  });
});

