export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemBasePremium(item), 0);

const itemsGroupedByType = (items: Item[]): Item[][] => {
  const byType = new Map<string, Item[]>();
  for (const item of items) {
    byType.set(item.type, [...(byType.get(item.type) ?? []), item]);
  }
  return [...byType.values()];
};

const formsBlock = (sameTypeItems: Item[]): boolean => sameTypeItems.length === BLOCK_SIZE;

const sameTypeBasePremium = (sameTypeItems: Item[]): number =>
  formsBlock(sameTypeItems) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(sameTypeItems);

const policyBasePremium = (items: Item[]): number =>
  itemsGroupedByType(items).reduce(
    (sum, sameTypeItems) => sum + sameTypeBasePremium(sameTypeItems),
    0,
  );

const withFirstInsuranceSurcharge = (policyBase: number): number =>
  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;

const roundPremiumInMHPCOsFavor = Math.ceil;

const CURSE_SURCHARGE = 0.5;

const itemSurcharge = (item: Item): number =>
  item.cursed === true ? itemBasePremium(item) * CURSE_SURCHARGE : 0;

const totalItemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemSurcharge(item), 0);

const premiumBeforeFee = (items: Item[]): number =>
  withFirstInsuranceSurcharge(policyBasePremium(items)) + totalItemSurcharges(items);

const quotePremium = (items: Item[]): number =>
  roundPremiumInMHPCOsFavor(premiumBeforeFee(items) + PROCESSING_FEE);

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") {
    return { premium: quotePremium(step.items) };
  }
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

