export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemBasePremium(item), 0);

const itemsGroupedByType = (items: Item[]): Item[][] => {
  const byType = new Map<string, Item[]>();
  for (const item of items) {
    byType.set(item.type, [...(byType.get(item.type) ?? []), item]);
  }
  return [...byType.values()];
};

const formsBlock = (sameTypeItems: Item[]): boolean => sameTypeItems.length === BLOCK_SIZE;

const sameTypeBasePremium = (sameTypeItems: Item[]): number =>
  formsBlock(sameTypeItems) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(sameTypeItems);

const policyBasePremium = (items: Item[]): number =>
  itemsGroupedByType(items).reduce(
    (sum, sameTypeItems) => sum + sameTypeBasePremium(sameTypeItems),
    0,
  );

const withFirstInsuranceSurcharge = (policyBase: number): number =>
  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;

const roundPremiumInMHPCOsFavor = Math.ceil;

const HIGH_ENCHANTMENT_THRESHOLD = 5;

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

interface RiskSurcharge {
  appliesTo: (item: Item) => boolean;
  rateOfBasePremium: number;
}

const RISK_SURCHARGES: RiskSurcharge[] = [
  { appliesTo: isCursed, rateOfBasePremium: 0.5 },
  { appliesTo: isHighlyEnchanted, rateOfBasePremium: 0.3 },
];

const itemRiskSurcharge = (item: Item): number =>
  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
    (sum, surcharge) => sum + itemBasePremium(item) * surcharge.rateOfBasePremium,
    0,
  );

const totalRiskSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemRiskSurcharge(item), 0);

const LOYALTY_DISCOUNT = 0.2;
const LOYALTY_THRESHOLD_YEARS = 2;

const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;

const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
  isLoyal(customer) ? policyBase * LOYALTY_DISCOUNT : 0;

const policyWidePremium = (policyBase: number, customer: Customer): number =>
  withFirstInsuranceSurcharge(policyBase) - loyaltyDiscount(policyBase, customer);

const premiumBeforeFee = (items: Item[], customer: Customer): number =>
  policyWidePremium(policyBasePremium(items), customer) + totalRiskSurcharges(items);

const quotePremium = (items: Item[], customer: Customer): number =>
  roundPremiumInMHPCOsFavor(premiumBeforeFee(items, customer) + PROCESSING_FEE);

const runStep = (step: Step, customer: Customer): StepResult => {
  if (step.op === "quote") {
    return { premium: quotePremium(step.items, customer) };
  }
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
});

