const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

interface Policy {
  items: Item[];
  remainingCap: number;
}

const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE_PER_DAMAGE;

const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
  const payout = incident.damages.reduce((sum, damage) => sum + damagePayout(damage), 0);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const policies = new Map<number, Policy>();
  const results: StepResult[] = [];

  scenario.steps.forEach((step, stepIndex) => {
    if (step.op === "quote") {
      policies.set(stepIndex, {
        items: step.items,
        remainingCap: insuranceSum(step.items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
      });
      results.push({
        premium: quotePremium(step.items, {
          customer: scenario.customer,
          isFollowUpContract: policies.size > 1,
        }),
      });
      return;
    }

    const policy = policies.get(step.policy);
    if (policy === undefined) {
      throw new Error(`Unknown policy: ${step.policy}`);
    }
    results.push(settleClaim(policy, step.incident));
  });

  return { results };
};

