/** Each damage entry is settled against its own insured item, so a policy covering two
 *  swords can suffer two separate sword damages — but never more than it covers. */
const takeDamagedItem = (unclaimedItems: Item[], damage: Damage): Item => {
  const index = unclaimedItems.findIndex((item) => item.type === damage.itemType);
  if (index === -1) {
    throw new Error(`Item not covered by policy: ${damage.itemType}`);
  }
  return unclaimedItems.splice(index, 1)[0];
};

/** What the incident is worth before the policy's cap is taken into account. */
const grossIncidentPayout = (incident: Incident, insuredItems: Item[]): number => {
  const unclaimedItems = [...insuredItems];
  return incident.damages.reduce(
    (sum, damage) =>
      sum + damageAmountAfterDeductible(damage, takeDamagedItem(unclaimedItems, damage)),
    0,
  );
};

